import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    public static BigInteger A(int n, int k) {
        return factorial(n).divide(factorial(n - k));
    }

    public static void process() {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        String[] parts = line.trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int mod = Integer.parseInt(parts[1]);
        if (n == 1) {
            System.out.println(0);
            return;
        }
        int[] z_list = {1};
        long total_value = 0;
        for (int i = 2; i <= n; i++) {
            int size = (i * i) / 2;
            int[] next_z = new int[size];
            for (int j = 0; j < z_list.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (z_list[j] > 0) {
                        int index = i - k - 1 + j;
                        if (index >= 0 && index < next_z.length) {
                            next_z[index] += z_list[j];
                        }
                    }
                }
            }
            int[] prefix_sum = new int[z_list.length + 1];
            for (int w = z_list.length - 1; w >= 0; w--) {
                prefix_sum[w] = (prefix_sum[w + 1] + z_list[w]) % mod;
            }
            long[] e_array = new long[prefix_sum.length];
            long[] f_array = new long[prefix_sum.length];
            for (int w = 0; w < prefix_sum.length - 1; w++) {
                e_array[w + 1] = (e_array[w] + prefix_sum[w]) % mod;
                f_array[w + 1] = (f_array[w] - (long)w * prefix_sum[w]) % mod;
                if (f_array[w + 1] < 0) f_array[w + 1] += mod;
            }
            long total_value_local = 0;
            for (int jj = 0; jj < z_list.length; jj++) {
                int L = jj + 2;
                int R = Math.min(z_list.length - 1, i + jj);
                long ccc = 0;
                if (R >= L) {
                    long e_diff = e_array[R + 1] - e_array[L];
                    long f_diff = f_array[R + 1] - f_array[L];
                    e_diff %= mod;
                    f_diff %= mod;
                    ccc = ((e_diff * (long)(i + 1 + jj)) % mod + f_diff) % mod;
                }
                total_value_local = (total_value_local + ccc * z_list[jj]) % mod;
            }
            BigInteger aVal = A(n, n - i);
            long aValMod = aVal.mod(BigInteger.valueOf(mod)).longValue();
            total_value = (total_value + total_value_local + total_value_local * aValMod) % mod;
            z_list = next_z;
        }
        System.out.println(total_value % mod);
        scanner.close();
    }

    public static void main(String[] args) {
        process();
    }
}
